rules.code:
// ✓ Native button — keyboard, focus, and announcement included
<button onClick={handleClick}>Submit</button>

// ✗ div 'button' — you still wire up all keyboard events yourself
<div role="button" tabIndex={0}
  onClick={handleClick}
  onKeyDown={e => {
    if (e.key === 'Enter' || e.key === ' ') handleClick();
  }}
>
  Submit
</div>

// polite: waits for current speech to finish
<div role="status" aria-live="polite">
  {resultCount !== null && `Showing ${resultCount} results`}
</div>

// assertive: interrupts immediately — use sparingly
<div role="alert" aria-live="assertive">
  {errorMessage}
</div>

// ✓ Hide decorative icon from SR — it's not focusable
<svg aria-hidden="true" focusable="false">...</svg>

// ✗ Never hide something keyboard users can still reach
<button aria-hidden="true">Submit</button>
